@property
def calmar(self):
    if len(self.monthly_rets) < 3:
        return -999.0
    r = np.array(self.monthly_rets)
    eq = np.cumprod(1 + r)
    peak = np.maximum.accumulate(eq)
    mdd = float((eq / peak - 1).min())
    if mdd >= 0:
        return -999.0
    n_yr = len(r) / 12
    ann = eq[-1] ** (1 / n_yr) - 1 if eq[-1] > 0 else -1
    return ann / abs(mdd)

